package com.nhlocal.singlesorter.app;
/** Fixed vocabulary only; never leaks paths, metadata, or an arbitrary provider exception. */
final class ReadinessDiagnostic {
 private ReadinessDiagnostic(){}
 static String code(Throwable failure){String text=failure.getMessage();if(text==null)return "UNCLASSIFIED_REFUSAL";
  if(text.matches("ALBUM_PARENT_(BINDING|SOURCE|SCOPE|OBSERVATION|DIRECT_CHILD|SELECTION|CHANGED|UNAVAILABLE|AMBIGUOUS|INCOMPLETE|BOUND|URI_BOUND|ORDER|REVIEW_BINDING|FRESH_SELECTION_REQUIRED)"))return text;
  for(String code:new String[]{"ANCESTRY_UNAVAILABLE","LOCAL_DOCUMENT_REQUIRED","RECOVERY_REQUIRED","RECOVERY_ROOT_MODE","RECOVERY_SCOPE_BUDGET","RETAINED_PROVIDER_OBJECT","RESERVED_PARENT_UNAVAILABLE","RESERVED_CHECK_BUDGET","RESERVED_SCOPE_LIMIT","RESERVED_CERTIFICATE_BUDGET","RESERVED_RETURN_SHAPE","RESERVED_URI_SHAPE","LOCAL_PROVIDER_REQUIRED","SYSTEM_LOCAL_PROVIDER_REQUIRED","PICKER_WRITE_GRANT_REQUIRED","SOURCE_TARGET_OVERLAP","ORIGINAL_PLAN_BLOCKED","ORIGINAL_FIX_BLOCKED","ORIGINAL_METADATA_BLOCKER_UNRESOLVED","FIX_JOB_BUDGET","FIX_EVENT_BUDGET","FIX_AUTHORITY_BUDGET","FIX_URI_BUDGET","FIX_ERROR_BUDGET","FIX_SOURCE_BINDING","FIX_PLAN_SHAPE","FIX_OPERATION_REQUIRED","FIX_RENAME_EFFECT_MISSING","ALBUM_SUBTREE_INCOMPLETE","ALBUM_JOB_BUDGET","ALBUM_URI_BUDGET","ALBUM_SELECTED_ROOT_REMOVAL_UNAVAILABLE","ALBUM_CHILD_NAME_AMBIGUOUS","ALBUM_RECOVERY_EVIDENCE","ALBUM_ORIGINAL_EFFECT_MISMATCH","ALBUM_DESTINATION_OCCUPIED","ALBUM_TREE_CHANGED","ALBUM_MEMBERSHIP_CHANGED","ALBUM_CONTENT_CHANGED","ALBUM_CREATE_EFFECT_MISMATCH","ALBUM_MOVE_EFFECT_MISMATCH","ALBUM_RENAME_EFFECT_MISMATCH","TARGET_DIRECTORY_OBSERVATION_UNAVAILABLE","TARGET_CHANGED_SINCE_OBSERVATION","TARGET_REMOVED_SINCE_PREVIEW","TARGET_ADDED_OR_REPARENTED"})if(text.equals(code)||text.startsWith(code+":"))return code;
  if(text.startsWith("recovery "))return "RECOVERY_RECORD_INVALID";return "UNCLASSIFIED_REFUSAL";
 }
}
